1448	pub fn submit_action(state: &GameState, action: &Action, registry: &CardRegistry) -> GameState {
1449	    let mut new_state = state.clone();
1450	    new_state.events.clear();
1451	
1452	    match action {
1453	        Action::PassPriority => {
1454	            let player = new_state.priority_player.unwrap_or(new_state.active_player);
1455	            new_state.events.push(GameEvent::PriorityPassed { player });
1456	            new_state.log(LogLevel::Debug, format!("p{} passes priority", player.0));
1457	            new_state.consecutive_passes += 1;
1458	        }
1459	
1460	        Action::PlayLand { object_id } => {
1461	            let player = new_state.priority_player.expect("PlayLand requires priority");
1462	            new_state.move_object(*object_id, Zone::Battlefield);
1463	            // Remove from library order if somehow there (shouldn't be, it's in hand).
1464	            new_state.get_player_mut(player).land_plays_remaining -= 1;
1465	            new_state.events.push(GameEvent::LandPlayed {
1466	                player,
1467	                object: *object_id,
1468	            });
1469	            // EnteredBattlefield is now emitted by move_object.
1470	            // Lands don't have summoning sickness (only creatures care).
1471	            if let Some(obj) = new_state.get_object_mut(*object_id) {
1472	                obj.summoning_sick = false;
1473	            }
1474	            let name = card_name(&new_state, registry, *object_id);
1475	            new_state.log(LogLevel::Info, format!("p{} played {}", player.0, name));
1476	            new_state.consecutive_passes = 0;
1477	        }
1478	
1479	        Action::CastSpell { object_id, targets, sacrifice, exile_count, alternative_cost } => {
1480	            let player = new_state.priority_player.expect("CastSpell requires priority");
1481	
1482	            // Detect flashback vs cast-from-graveyard.
1483	            // Flashback: card has flashback_cost or dynamically granted flashback.
1484	            // Cast-from-graveyard: card has can_cast_from_graveyard() (Skaab Ruinator) — uses normal mana cost.
1485	            let card_id = new_state.get_object(*object_id).expect("CastSpell object must exist").card_id;
1486	            let data = registry.get(card_id).expect("card must be in registry").card_data();
1487	            let behavior = registry.get(card_id).expect("card must be in registry");
1488	            let in_graveyard = new_state.get_object(*object_id)
1489	                .map(|o| o.zone == Zone::Graveyard)
1490	                .unwrap_or(false);
1491	            let is_cast_from_graveyard = in_graveyard && behavior.can_cast_from_graveyard();
